11	INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (197, NULL, 5, NULL, 'EN', 1, 'clinical', 'intrinsic', 'eutils.ncbi.nlm.nih.gov PubMed: wheelchair AND (turning space OR turning radius OR maneuvering space) AND (dimensions OR anthropometry OR clearance)', NULL, 'pubmed', 'scoping', NULL, 4, 4, 0, 'partial', NULL, NULL, 0, 'session_2026-11-06-pipeline-batch', '2026-11-06 02:49', 'Four hits, three on topic: Koontz 2010 (PMID 20434614, T1 case series, n=223, minimum passageway widths for L-turn, 360-degree turn and U-turn); Steinfeld 2010 (PMID 20402047, international comparison of anthropometry and standards); King 2011 (PMID 21657823, scooter three-point-turn areas). One off topic (PMID 36038463, a Delphi study of the word wheelchair-bound). None admitted: Europe PMC reports no open full text for Koontz or Steinfeld (isOpenAccess N, inPMC N), and the abstracts state no dimension, so an admission would add no extractable figure. Koontz and King DOIs are held as RETIRED stash rows (REF-00784, REF-00972): a re-admission cross-files to those ids. Query shape: well-formed; PubMed parsed turning space as turning AND space. Count 4 is below the prior floor of 5; the shortfall reads as an indexing fact (the main US report is not in PubMed), not a query-shape failure.', 0, 'Stated in the session transcript before the search ran: 5-25 hits; at most 1-2 usable measurement studies; the US anthropometry report (Steinfeld et al. 2010) may not be indexed in PubMed; full text unlikely.', 'planned', NULL, NULL, '2026-11-06 02:49', 'session_2026-11-06-pipeline-batch', NULL, NULL, NULL, NULL);
12	INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (198, NULL, 9, NULL, 'EN', 1, 'co1', 'intrinsic', 'eutils.ncbi.nlm.nih.gov PubMed: (wheelchair OR "people with disabilities") AND (doorway OR "door width" OR "corridor width") AND (participatory OR "focus group" OR "lived experience")', NULL, 'pubmed', 'scoping', NULL, 1, 1, 0, 'none', NULL, NULL, 0, 'session_2026-11-06-pipeline-batch', '2026-11-06 02:49', 'ZERO-YIELD for Co-1: the one hit (PMID 18002971, Cooper et al. 2007, robotics for personal mobility) reports focus-group participants naming doorways as a barrier but is an engineering overview, not a participatory dimension study; not a Co-1 source for a door or corridor width and not admitted. R14 diagnosis: QUERY-SHAPE FAILURE, not genuine absence. Three AND-ed concept groups; PubMed does not index participatory design-standard work from disabled persons organisations, which publishes as grey reports. A Co-1 retrieval for door and corridor widths is NOT done by this batch and stays open.', 0, 'Stated in the session transcript before the search ran: 0-3 hits, none qualifying as Co-1; if empty, the likelier cause is three AND-ed concept groups rather than genuine absence.', 'planned', NULL, NULL, '2026-11-06 02:49', 'session_2026-11-06-pipeline-batch', NULL, NULL, NULL, NULL);
