30	INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (179, 'REF-00992', NULL, 8, 'BLIND', NULL, NULL, NULL, 'UK', 'two adjoining surfaces; default case', 'numerical', '30', 'points', 'in light reflectance value between the two surfaces is greater than 30 points.', 'Approved Document M Volume 2, para 0.26, definition of contrast visually', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '0', NULL, '0.26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 17 of 74; 2015 edition incorporating 2020 and 2024 amendments', 'skim', 'preliminary', NULL, 'Quantity: difference in light reflectance value (LRV, 0 to 100 scale) between two surfaces for them to count as contrasting visually. The sentence begins on the previous page (PDF page 16 ends "the difference"); the quote starts at the page break. Strictly greater than 30 points. Lens BLIND is the reader''s reading, not the source''s statement [ASSUMPTION: paras 3.8 and 3.12 give people with impaired sight as the reason for visual contrast of doors and walls].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>');
31	INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (180, 'REF-00992', NULL, 8, 'BLIND', NULL, NULL, NULL, 'UK', 'two adjoining surfaces; illuminance above 200 lux', 'numerical', '20', 'points', 'Where illuminance on surfaces is greater than 200 lux, a difference in light reflectance value should be a minimum of 20 points.', 'Approved Document M Volume 2, para 0.26, definition of contrast visually', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '0', NULL, '0.26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 17 of 74; 2015 edition incorporating 2020 and 2024 amendments', 'skim', 'preliminary', NULL, 'Quantity: reduced LRV difference permitted where illuminance on the surfaces exceeds 200 lux. A relaxation of the 30 point figure, stated as an alternative, not as a condition on a row of another parameter (illuminance is not a parameter here). Lens BLIND is the reader''s reading, not the source''s statement [ASSUMPTION: as the 30 point row].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>=');
32	INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (181, 'REF-00992', NULL, 8, 'BLIND', NULL, NULL, NULL, 'UK', 'door opening furniture projecting beyond the face of the door', 'numerical', '15', 'points', 'Where door opening furniture projects beyond the face of the door or otherwise creates enhanced differentiation and shade, a minimum difference in light reflectance value of 15 points is considered adequate.', 'Approved Document M Volume 2, para 0.26, definition of contrast visually', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '0', NULL, '0.26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 17 of 74; 2015 edition incorporating 2020 and 2024 amendments', 'skim', 'preliminary', NULL, 'Quantity: reduced LRV difference considered adequate where door opening furniture projects or otherwise creates differentiation and shade. A relaxation of the 30 point figure. Lens BLIND is the reader''s reading, not the source''s statement [ASSUMPTION: as the 30 point row].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>=');
33	INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (182, 'REF-00987', NULL, 4, 'MOB', NULL, NULL, NULL, 'US', 'accessible routes', 'numerical', '915', 'mm', 'the clear width of walking surfaces shall be 36 inches (915 mm) minimum.', '2010 ADA Standards for Accessible Design, 403.5.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4', '403.5.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ada.gov 2010 Standards page, HTML as retrieved 2026-10-30', 'skim', 'preliminary', NULL, 'Quantity: minimum clear width of a walking surface on an accessible route. The source states inches with the millimetre figure beside it; the millimetre figure is the one filed. The exception permits 815 mm for a length of 610 mm maximum, with 1220 mm long, 915 mm wide segments between; not filed as a row. Lens MOB is the reader''s reading, not the source''s statement [ASSUMPTION: chapter 4 is titled accessible routes and the surrounding clauses (403.5.2) set widths for turning around wheelchair-sized elements].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>=');
34	INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (183, 'REF-00987', NULL, 5, 'MOB', NULL, NULL, NULL, 'US', 'turning space, circular', 'numerical', '1525', 'mm', 'The turning space shall be a space of 60 inches (1525 mm) diameter minimum.', '2010 ADA Standards for Accessible Design, 304.3.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '3', '304.3.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ada.gov 2010 Standards page, HTML as retrieved 2026-10-30', 'skim', 'preliminary', NULL, 'Quantity: minimum diameter of the circular turning space. 304.3.2 allows a T-shaped space within a 1525 mm square as the alternative; not filed as a row. Millimetre figure filed as stated beside the inch figure. Lens MOB is the reader''s reading, not the source''s statement [ASSUMPTION: section 304 is titled turning space and is a wheelchair provision].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>=');
