36	INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (185, 'REF-00987', NULL, 9, 'MOB', NULL, NULL, NULL, 'US', 'door openings; clear width', 'numerical', '815', 'mm', 'Door openings shall provide a clear width of 32 inches (815 mm) minimum.', '2010 ADA Standards for Accessible Design, 404.2.3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4', '404.2.3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ada.gov 2010 Standards page, HTML as retrieved 2026-10-30', 'skim', 'preliminary', NULL, 'Quantity: minimum clear width of a door opening, measured between the face of the door and the stop with the door open 90 degrees; 915 mm where the opening is more than 610 mm deep. Lens MOB is the reader''s reading, not the source''s statement [ASSUMPTION: the measurement basis is a swung-open door, the wheelchair-passage case].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>=');
